import type { MultiSelectProps, MultiSelectContextType } from "./multi-select.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Menu } from "@components/menu";

import {
  MultiSelectTrigger,
  MultiSelectContent,
  MultiSelectItem,
  MultiSelectItems,
  MultiSelectSearch,
  MultiSelectIcon,
  MultiSelectAvatarChip,
  MultiSelectChip,
  MultiSelectChipCloseButton,
  MultiSelectValues,
  MultiSelectClearIconButton,
} from "./subcomponents";
import { MultiSelectClasses, StyledMultiSelect } from "./multi-select.styles";
import { MultiSelectContext, useMultiSelectState } from "./hooks/use-multi-select";

const MultiSelectRoot = forwardRef(
  (
    {
      announcementFormatter,
      children,
      className,
      deduplicateOptions = true,
      defaultOpen = false,
      defaultValue = [],
      disabled = false,
      offset = 4,
      onOpenChange,
      onValueChange,
      options = [],
      placeholder,
      sort,
      sortSelectedFirst = true,
      style,
      value: valueProp,
      variant = "default",
      name,
      "aria-invalid": ariaInvalid,
      "aria-describedby": ariaDescribedby,
      "aria-labelledby": ariaLabelledBy,
      "aria-required": ariaRequired,
      required,
      id,
      ...props
    }: MultiSelectProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(MultiSelectClasses.root, className);
    const state = useMultiSelectState({
      value: valueProp,
      defaultValue,
      onValueChange,
      defaultOpen,
      onOpenChange,
      options,
      children,
      deduplicateOptions,
      sort,
      sortSelectedFirst,
      announcementFormatter,
    });

    const contextValue: MultiSelectContextType = {
      ...state,
      isOpening: state.isOpening,
      disabled,
      theme,
      variant,
      styleSlots: props.styleSlots,
      placeholder,
      "aria-invalid": ariaInvalid,
      "aria-describedby": ariaDescribedby,
      "aria-labelledby": ariaLabelledBy,
      "aria-required": ariaRequired,
      required,
      id,
    };

    return (
      <MultiSelectContext.Provider value={contextValue}>
        <StyledMultiSelect
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          style={{
            cursor: disabled ? "not-allowed" : "pointer",
            ...style,
          }}
          variant={variant}
          {...props}
        >
          <Menu
            open={state.open}
            sideOffset={offset}
            styleSlots={{
              group: {
                display: "flex",
                flexDirection: "column",
                flex: 1,
                minHeight: 0,
                overflow: "hidden",
                height: "100%",
                padding: 0,
              },
              content: {
                maxHeight: "var(--radix-popper-available-height)",
                display: "flex",
                flexDirection: "column",
                overflow: "hidden",
              },
            }}
            onOpenChange={state.setOpen}
          >
            {children}
          </Menu>
          {name &&
            state.value.map((val) => <input key={val} name={name} type="hidden" value={val} />)}
          <div aria-live="polite" className="sr-only">
            {state.announcement}
          </div>
        </StyledMultiSelect>
      </MultiSelectContext.Provider>
    );
  },
);

MultiSelectRoot.displayName = "MultiSelect";

const MultiSelect = Object.assign(MultiSelectRoot, {
  Trigger: MultiSelectTrigger,
  Content: MultiSelectContent,
  Item: MultiSelectItem,
  Items: MultiSelectItems,
  Search: MultiSelectSearch,
  Icon: MultiSelectIcon,
  AvatarChip: MultiSelectAvatarChip,
  Chip: MultiSelectChip,
  ChipCloseButton: MultiSelectChipCloseButton,
  Values: MultiSelectValues,
  ClearIconButton: MultiSelectClearIconButton,
  ItemLabel: Menu.ItemLabel,
  ItemSubtext: Menu.ItemSubtext,
  ItemLeadingIcon: Menu.ItemLeadingIcon,
  ItemTrailingIcon: Menu.ItemTrailingIcon,
});

export default MultiSelect;
